    ('prod-01', now() - interval '113760 minutes', now() - interval '1440 minutes', 'Áo sơ mi trắng Oxford cổ đức', 'Áo sơ mi trắng Oxford cổ đức thuộc dòng shirt của thương hiệu. Chất liệu oxford, form regular fit, thiết kế gọn gàng và dễ phối đồ. Phù hợp sử dụng quanh năm. Hướng dẫn bảo quản có trong thông tin sản phẩm.', 'ao-so-mi-trang-oxford-co-duc-01', 'Áo sơ mi trắng Oxford cổ đức - regular fit, chất liệu oxford, phù hợp quanh năm.', 'brand-lino', 'PUBLISHED', true, 'MEN', 'SHIRT', 569000, 529000, 'med-01', 'sc-shirt-men', 'Áo sơ mi trắng Oxford cổ đức | LINO Fashion', 'Áo sơ mi trắng Oxford cổ đức - regular fit, chất liệu oxford, phù hợp quanh năm.', now() - interval '99360 minutes', 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?w=800&auto=format&fit=crop&q=80', 300, 32, 25, 4),
    ('prod-02', now() - interval '112320 minutes', now() - interval '2880 minutes', 'Áo sơ mi xanh sọc nhỏ', 'Áo sơ mi xanh sọc nhỏ thuộc dòng shirt của thương hiệu. Chất liệu cotton 100%, form slim fit, thiết kế gọn gàng và dễ phối đồ. Phù hợp sử dụng quanh năm. Hướng dẫn bảo quản có trong thông tin sản phẩm.', 'ao-so-mi-xanh-soc-nho-02', 'Áo sơ mi xanh sọc nhỏ - slim fit, chất liệu cotton 100%, phù hợp quanh năm.', 'brand-noble', 'PUBLISHED', false, 'MEN', 'SHIRT', 599000, NULL, 'med-01', 'sc-shirt-men', 'Áo sơ mi xanh sọc nhỏ | LINO Fashion', 'Áo sơ mi xanh sọc nhỏ - slim fit, chất liệu cotton 100%, phù hợp quanh năm.', now() - interval '97920 minutes', 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?w=800&auto=format&fit=crop&q=80', 300, 32, 25, 4),
